const DATA = [
  { id: "p1", name: "雨夜车站", owner: "林夏", shots: 48, children: [
    { id: "p1-e1", name: "第 1 集", owner: "林夏", shots: 20, children: [
      { id: "p1-e1-s1", name: "第 1 场 · 车站外", owner: "林夏", shots: 12 },
